<script setup>import {onMounted,ref} from 'vue';import {api} from '../api';const now=new Date(),year=ref(now.getFullYear()),month=ref(now.getMonth()+1),data=ref({monthly:[]});async function load(){data.value=(await api.get('/module-reports/staff',{params:{year:year.value,month:month.value}})).data;}function money(v){return Number(v||0).toFixed(2)}onMounted(load);</script>
<template><h1>Staff / Payroll Report</h1><div class="toolbar"><label>Year<input type="number" v-model.number="year"></label><label>Month<select v-model.number="month"><option v-for="m in 12" :value="m">{{new Date(2000,m-1,1).toLocaleString('en',{month:'long'})}}</option></select></label><button @click="load">Apply</button></div><div class="grid"><div class="card"><div class="muted">Active Staff</div><div class="metric">{{data.activeStaff||0}}</div></div><div class="card"><div class="muted">Salary Payable</div><div class="metric">₹{{money(data.salaryPayable)}}</div></div><div class="card"><div class="muted">Salary Paid</div><div class="metric">₹{{money(data.salaryPaid)}}</div></div><div class="card"><div class="muted">Outstanding</div><div class="metric">₹{{money(data.salaryOutstanding)}}</div></div><div class="card"><div class="muted">Absent Entries</div><div class="metric">{{data.absentEntries||0}}</div></div><div class="card"><div class="muted">Half Days</div><div class="metric">{{data.halfDayEntries||0}}</div></div></div><div class="card" style="margin-top:18px"><h2>Month-wise Payroll</h2><table class="table"><tr><th>Month</th><th>Payable</th><th>Paid</th><th>Difference vs Previous Month</th></tr><tr v-for="x in data.monthly||[]" :key="x.month"><td>{{x.monthName}}</td><td>₹{{money(x.payable)}}</td><td>₹{{money(x.paid)}}</td><td :class="Number(x.differenceFromPreviousMonth)>=0?'positive-text':'danger'">{{Number(x.differenceFromPreviousMonth)>=0?'+':''}}₹{{money(x.differenceFromPreviousMonth)}}</td></tr></table></div></template>
